/* Boot #5 — animation d assemblage de l embleme (genere depuis _bake, 3x3=9 blocs, 32 frames).
   Pilote #boot-emblem : joue l assemblage (~1.5s) puis idle, en boucle, jusqu au retrait du splash. */
window.__BOOT_FRAMES=["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];
(function(){
  var reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
  var F=window.__BOOT_FRAMES, emb=document.getElementById("boot-emblem");
  if(!emb||!F||!F.length) return;
  var imgs=F.map(function(s){var i=new Image();i.src=s;return i;});
  var timer=null;
  function alive(){ return !!document.getElementById("boot"); }
  function settle(){ var b=document.getElementById("boot"); if(!b)return; b.classList.add("settled"); if(!reduce) timer=setTimeout(play,2600); }
  function play(){ var b=document.getElementById("boot"); if(!b)return; b.classList.remove("settled");
    if(reduce){ emb.src=F[F.length-1]; settle(); return; }
    var f=0, step=1500/F.length;
    (function next(){ if(!alive())return; emb.src=F[f]; if(f>=F.length-1){ settle(); return; } f++; timer=setTimeout(next,step); })();
  }
  Promise.all(imgs.map(function(i){return i.decode?i.decode().catch(function(){}):Promise.resolve();})).then(play);
})();